#include <cstdio>#include <cstring>#include <cctype>#include <algorithm>#include <iostream>#include <queue>typedef long long LL;using namespace std;inline LL read() {    LL num = 0 ,f = 1; char c = getchar();    while (!isdigit(c)) f = c == '-' ? -1 : f ,c = getchar();    while (isdigit(c)) num = (num << 1) + (num << 3) + (c ^ 48) ,c = getchar();    return num * f;}const int N = 2e5 + 5;inline void bronya_solve() {    LL n = read();    int res = 0;    for (int i = 1; i <= 1000; i++) if (n % i) {res = i - 1; break;}    printf("%d\n" ,res);}signed main() {    int t = read();    while (t--) bronya_solve();    return 0;}